      "565140087": "GLOOM BASE ALPHA",
      "567695062": "ANGEL'S VENTURE",
      "568622358": "VARYLIA 5",
      "572820359": "MINERVA",
      "574108092": "FRAKENEERIA",
      "584255963": "DARROWSPORT",
      "588827542": "The DSS deploys <i=1>Eagle Strafing Runs</i> during missions.",
      "591927688": "EXPERIMENTAL SUPER SOLDIERS",
