      "652324972": "DEV_06",
      "655206231": "CLASA",
      "655668011": "DOLPH",
      "661319112": "SUPER GLOOM BASE ALPHA",
      "664680323": "WAYWARD",
      "665934661": "The Helldiver has faster stamina regeneration and slowly regenerates health and injuries automatically.",
      "666686095": "Intel Packages are compromised. Picking them up will notify the enemy of your whereabouts and cause an encounter.",
      "671544406": "The former site of the Deep Mantle Forge Complex, stolen by the Automatons and destroyed.",
      "677430713": "MEKBUDA",
      "688744041": "This planet is completely engulfed by the Gloom, severely impeding logistical support.\nExtraction times are increased by <i=1>40 seconds,</i> Eagle Re-arm time is increased by <i=1>30%</i> and Ammo from pickups is reduced by <i=1>50%.</i>",
      "689956975": "TARSH",
      "690834076": "PRASA",
      "696771573": "PENNYBRIDGE",
      "702284474": "WATCHDOG 5",
      "707866417": "The Illuminate invasion fleet, constructed in secret behind the veil of the Meridian Wormhole. It is headed for Super Earth itself.",
      "708743426": "POLARIS PRIME",
      "710416841": "IRO",
      "710669387": "BUNDA SECUNDUS",
      "711960853": "VOID SOURCE PLANET",
      "717015403": "CENTER OF SCIENCE (DESTROYED)",
      "730425751": "ELYSIAN MEADOWS",
      "740173750": "VALMOX",
      "740677481": "WEAPONS EXPERIMENTATION",
      "746457430": "AVILA",
      "761483845": "Helldivers deploy with <i=1>#V_ONE%</i> less magazines.",
      "762468820": "NEW ASPIRATION CITY",
      "765324963": "The presence of the DSS near this planet provides a slight boost to <i=1>Liberation Campaign</i> progress.",
      "770494850": "UNMAPPED SYSTEM",
      "771961394": "HELLMIRE",
      "774406423": "HYDROBIUS",
      "775857686": "TERREK",
      "778160541": "WRAITH",
      "779490921": "A mine extracting platinum from deep-seated deposits of igneous rock.",
      "782903598": "SKAASH",
      "785130403": "DEV_05",
      "796165462": "The Automatons have deployed a series of specialized models on this planet. Prepare to face bots upgraded with stolen Jump Pack technology.",
      "803894884": "BRILLIANCE",
      "805511186": "PHACT BAY",
      "807737937": "DATA CENTER",
      "810343458": "The top-secret site where augmentations to the DSS are constructed.",
      "810565547": "INVASION FLEET",
      "817785996": "SPHERION",
      "820622353": "MEISSA",
      "823091821": "EQUIPMENT TESTING",
      "824899430": "ADDITIONAL PAYOUT",
      "826900961": "WEAPONS EXPERIMENTATION",
      "832453372": "The prosperous Meridia was corrupted into a Terminid Supercolony, necessitating its destruction using the mysterious Dark Fluid. This galactic scar is all that remains. Advisory: volatile spacetime fluctuations currently prohibit FTL travel to the Meridian Black Hole.",
      "833603519": "ANDWELL",
      "846577287": "VOLTERRA",
      "847733001": "E-710 FARMS",
      "848932066": "ORBITAL BLOCKADE",
      "853684841": "PREDATOR STRAIN",
