      "1298431672": "LASTOFE",
      "1317730141": "KEID",
      "1318124552": "OVERGOE PRIME",
      "1318718284": "ATTACK INCREASE",
      "1319973008": "The Illuminate have unleashed the next wave of their democratically voided thralls on this planet. Expect violent voter suppression tactics.",
      "1333202479": "PLANETARY BOMBARDMENT",
      "1342954337": "AIN-5",
      "1362615920": "LIGHT GLOOM COVER",
      "1375930354": "PILEN V",
      "1382288454": "NABATEA SECUNDUS",
      "1396860769": "INTER-GALACTIC NETWORK NODE",
      "1407696270": "NEW STOCKHOLM",
      "1423642964": "The extensive Terminid enclosures here allow scientists to study Terminid behavior, and civilians to take pictures with Brood Commanders.",
      "1427924894": "This planet continually produces a thick atmospheric Gloom cover, rendering logistical support extremely challenging.\nTotal Reinforcements are reduced by <i=1>20%,</i> Eagle Re-arm time is increased by <i=1>30%</i> and Ammo from pickups is reduced by <i=1>50%.</i>",
      "1437811852": "CALYPSO",
      "1441504339": "SUPER EARTH",
      "1443392861": "REAF",
      "1451959923": "BOREA",
      "1465854050": "NAVI VII",
      "1466635519": "NEW WISDOM",
      "1468076040": "ZZANIAH PRIME",
      "1472672983": "<i=1>50%</i> bonus to <i=1>Requisition</i> and <i=1>XP</i> awarded per mission",
      "1475087488": "SOCORRO III",
      "1483133390": "HULK SURGE",
