      "1598896052": "The location of Intel is  indicated on the mini-map.",
      "1604430375": "DEV_09",
      "1623115737": "The Jump Pack stratagem is temporarily available to all Helldivers.",
      "1626212068": "HOPEFUL",
      "1628213888": "MODERATE GLOOM BLANKET",
