      "3514565128": "增加戰場彈藥",
      "3519536123": "北斗二",
      "3533018389": "光能者的主力入侵艦隊已降臨該星球，包括傲慢的監督者和遭到洗腦的超級地球平民。一經發現請格殺勿論，否則恐將面臨暴力抵抗，更甚者，叛國文宣。",
      "3539223805": "負面能量實驗室",
      "3552972191": "憂霾粒子干擾塘鵝著陸，撤離時間增加<i=1>20秒</i>。",
      "3554352793": "深地函鍛造複合廠區（遺址）",
      "3564151658": "引力錨",
      "3567969782": "梅里迪亞蟲洞是由光能族所創造，曾被用來摧毀整顆星球，甚至威脅到超級地球本身。經授權的訪客可在此處觀看這個毀滅性的奇點，提醒自己，為何我們的敵人應被徹底殲滅。",
      "3570922568": "天狼星II",
      "3580449947": "龍蟑",
      "3584260041": "威農井",
      "3595804220": "真理部在這裡分析公民的活動、言論、資料、DNA、RNA和神經構造。",
      "3598277119": "生化斯坦",
      "3603869762": "凱文諾",
      "3607018920": "拉斯普",
      "3610215261": "憂霾研究設施",
      "3618005346": "垂直強化的噴射隊士兵就是在這裡生產的。",
      "3621980142": "堤比特",
      "3626758819": "天龍座",
      "3628603089": "與其他星球相比，這個星球的無權者成長速度似乎更快。",
      "3630129367": "杜馬提",
      "3632688076": "喧沌",
      "3643666565": "光能者此次僅部署其同類於該星球，此舉明確顯示本次行動具有高度戰略重要性及排外本質。準備迎戰步兵單位、無人機，以及受操控的機械構裝體。",
      "3667756654": "輦道二CXI",
      "3669186559": "研究蟲族行為、生態和E-710潛力的人員聚集在此進行跨學科研究。",
      "3679110529": "外層風暴鋒面正匯聚為高密度氣壓系統，威脅足以吞噬整顆星球。",
      "3689757614": "鳩鴿科",
      "3692813988": "哈都斯",
      "3702357685": "虛無通道",
      "3704017479": "昴宿一灣",
      "3709010725": "天市右垣九",
      "3709494312": "霸王蟲",
      "3711039703": "<i=1>飛鷹重新武裝</i>時間減緩<i=1>#V_ONE%</i>。",
      "3722503053": "凱拉",
      "3725356541": "塞伯拉斯IIIc",
      "3726554027": "極光灣",
      "3726809868": "穿著高效隔熱服的公民在此地操作從機器人手中解放並重新改造的設施，以便能在這顆火山活動頻繁的星球上持續地開採稀有資源。",
      "3746837729": "皮耶阿",
      "3749126267": "UVP貝塔",
      "3756969656": "勇氣",
      "3767503173": "歐拉斯",
      "3771554627": "憂霾研究探險隊",
      "3787865575": "<i=1>軌道120mm高爆彈彈幕</i>經實驗性質的改造，加入更多高爆彈、電磁炮，並縮小半徑。",
      "3792296541": "德勞普尼",
      "3798493358": "<i=1>解放戰役</i>的進展加速。",
      "3820781527": "裝備測試",
      "3825744973": "解放日慶典",
      "3835584257": "協力",
      "3848186075": "E-711開採設施",
      "3861654825": "減少戰場彈藥",
      "3868806488": "歐巴里",
      "3876920205": "目的不明的樞紐",
      "3886945884": "闔家歡",
      "3891463586": "烏巴內亞",
      "3892609265": "極端溫度採掘廠",
      "3904473600": "林杜默",
      "3909684051": "印博",
      "3914500540": "北河二",
      "3937567880": "戴米爾格",
      "3939430458": "天樽二",
      "3940422141": "失落",
      "3949569347": "耶利瓦",
      "3955894400": "十字架一",
      "3957075233": "重度憂霾籠罩",
      "3962567934": "克里姆錫卡",
      "3965403289": "普羅維登斯",
      "3970498706": "孔雀十一",
      "3971198333": "光能者會利用這顆星球上的設施將公民變成無權者。",
      "3974317902": "這個星球上，科學部的頂尖精英正致力推動下一個科技突破。",
      "3975465670": "保衛",
      "3978718279": "敏雀特",
      "3979919195": "異化昆蟲中心（遺址）",
      "3985499109": "五芒",
      "3988232937": "超級地球，我們的家園，是解放日慶典的核心。全體公民可一同透過電視轉播，共同觀賞年度防衛閱兵、正義處決，當然還有自由煙火秀。\n\n在這個特別的日子裡，我們鼓勵絕地戰兵返回超級地球，於自己的超級驅逐艦上觀賞今年的煙火表演。",
      "3997337233": "限時的憂霾探索行動正在該星球上展開，代價十分高昂。",
      "3998055819": "超級憂霾布拉沃基地",
      "4037455426": "工人們正在此星球興建三大最高安全等級城市的其中一座：這是對抗暴政的堡壘，堅不可摧。",
      "4050163919": "摩爾泰斯主星",
      "4053106192": "阿爾法哨站",
      "4056137100": "坦克激增",
      "4062016236": "新基魯納",
      "4064243582": "光能者打算將梅里迪亞奇異點推向超級地球。梅里迪亞奇異點路經之地的一切都將被粉碎。",
      "4082023109": "寡婦港",
      "4088126157": "瑪塔灣",
      "4089075400": "飛鷹風暴",
      "4093374049": "哈斯特",
      "4098458068": "抱負新城建設地",
      "4101241081": "異化昆蟲中心",
      "4116054022": "阿茲提拉",
      "4129150690": "異常地點",
      "4137490107": "阿得里治灣",
      "4142342788": "廢墟星系",
      "4155803285": "索嘉斯特",
      "4162129764": "DSS後勤艦隊向所有繞行星球的超級毀滅者，提供過剩的380mm砲彈。SEAF行動也會獲得軍械補給，加速解放行動。",
      "4164526636": "天鷹XXXII",
      "4164770624": "因格瑪",
      "4165159481": "仙蓋23號",
      "4165395098": "詭計",
      "4168695740": "艾列爾特III",
      "4185462613": "痛斥",
      "4185597853": "澤亞魯哥西亞",
      "4189958024": "在此星球上偵測到蟲族霸王蟲。準備迎戰大量破土而出的敵人。",
      "4193991609": "阿祖爾次星",
      "4209107572": "艾倫特",
      "4210400742": "零星的外層風暴區域正於星球各地湧現，風勢迅速增強。",
      "4212061343": "伯爾岩",
      "4218892298": "未註冊星系",
      "4219840211": "別克文III",
      "4224650510": "迪露維亞",
      "4225321155": "自由山脊",
      "4246407614": "公民監控及安全中心",
      "4255508129": "雙生II",
      "4256548577": "E-711源泉",
      "4275167981": "帕許",
      "4284868403": "嚮往新城建設地"
    }
  },
